      { role: "system", content: "Give two strengths and one suggestion for this essay." },
      { role: "user", content: "Student: " + studentName + "\n\n" + essay },
    ],
  });
  tokensToday += out.usage.total_tokens;
  res.json({ text: out.choices[0].message.content });
}

