export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/teacher") {
      return new Response("Calls so far: " + ((await env.KV.get("total")) || 0));
    }
    const ip = request.headers.get("CF-Connecting-IP");
    const key = "rl:" + ip;
    const n = Number((await env.KV.get(key)) || 0);
    if (n >= 20) return new Response("Too many requests", { status: 429 });
    await env.KV.put(key, String(n + 1), { expirationTtl: 60 });
    const total = Number((await env.KV.get("total")) || 0);
    await env.KV.put("total", String(total + 1));
    const { text } = await request.json();
    const r = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer __FAKE_MODEL_KEY__" },
      body: JSON.stringify({
        model: "gpt-4o-mini",
        messages: [
          { role: "system", content: "Suggest one way to improve this sentence." },
          { role: "user", content: text },
        ],
      }),
    });
    return new Response(await r.text(), { headers: { "Content-Type": "application/json" } });
  },
};

