let tokens = 0;
const DAILY_TOKEN_BUDGET = 150000;

async function ask(req, res) {
  let body = "";
  for await (const c of req) body += c;
  if (tokens > DAILY_TOKEN_BUDGET) { res.writeHead(429); return res.end("Budget used up"); }
  const r = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: "Bearer " + process.env.OPENAI_API_KEY },
    body: JSON.stringify({ model: "gpt-4o-mini", max_tokens: 120, messages: [
      { role: "system", content: "Define the word simply." }, { role: "user", content: JSON.parse(body).word } ] }),
  });
  const data = await r.json();
  tokens += data.usage.total_tokens;
  res.end(JSON.stringify({ reply: data.choices[0].message.content }));
}

http.createServer((req, res) => {
  if (req.url === "/api/ask") return ask(req, res);
  if (req.url === "/api/usage") return res.end(JSON.stringify({ tokens }));
  const file = path.join(process.cwd(), req.url === "/" ? "index.html" : req.url);
  fs.readFile(file, (err, data) => {
    if (err) { res.writeHead(404); return res.end("Not found"); }
    res.end(data);
  });
}).listen(3000);

