import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
const hits = new Map<string, { n: number; at: number }>();

export async function POST(req: Request) {
  const ip = req.headers.get("x-forwarded-for") ?? "unknown";
  const now = Date.now();
  const h = hits.get(ip);
  if (h && now - h.at < 60000 && h.n >= 5) return new Response("Too many questions", { status: 429 });
  hits.set(ip, h && now - h.at < 60000 ? { n: h.n + 1, at: h.at } : { n: 1, at: now });
  const { question } = await req.json();
  const msg = await client.messages.create({
    model: "claude-3-5-haiku-latest",
    max_tokens: 250,
    system: "Answer school questions briefly and kindly.",
    messages: [{ role: "user", content: question }],
  });
  return Response.json({ reply: msg.content[0].type === "text" ? msg.content[0].text : "" });
}

