export default {
  async fetch(request, env) {
    const ip = request.headers.get("x-real-ip") || "anon";
    const k = "votes:" + ip;
    if (request.method === "POST") {
      const used = Number((await env.POLL.get(k)) || 0);
      if (used >= 3) return new Response("Vote limit reached", { status: 429 });
      await env.POLL.put(k, String(used + 1), { expirationTtl: 300 });
      const { choice } = await request.json();
      const n = Number((await env.POLL.get("choice:" + choice)) || 0);
      await env.POLL.put("choice:" + choice, String(n + 1));
    }
    return new Response("ok");
  },
};

