import Anthropic from "@anthropic-ai/sdk";
import { spendToday, addSpend, DAILY_CLASS_BUDGET } from "@/lib/budget";

const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });

export async function POST(req: Request) {
  const { classCode, question } = await req.json();
  if ((await spendToday(classCode)) > DAILY_CLASS_BUDGET) {
    return Response.json({ reply: "This class has used its budget for today." }, { status: 429 });
  }
  const msg = await client.messages.create({
    model: "claude-3-5-haiku-latest",
    max_tokens: 300,
    system: "You are a homework helper. Explain the steps and do not hand over final results.",
    messages: [{ role: "user", content: question }],
  });
  await addSpend(classCode, msg.usage.input_tokens + msg.usage.output_tokens);
  return Response.json({ reply: msg.content[0].type === "text" ? msg.content[0].text : "" });
}

