// Provider keys look like long random strings; keep them in wrangler secrets, never in this file.
const DAILY_CLASS_BUDGET = 300000;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const day = new Date().toISOString().slice(0, 10);
    if (url.pathname === "/teacher") {
      const code = url.searchParams.get("code");
      return new Response("Tokens used today: " + ((await env.KV.get("class:" + code + ":" + day)) || 0));
    }
    const { learnerId, classCode, text } = await request.json();
    const lk = "learner:" + learnerId;
    const n = Number((await env.KV.get(lk)) || 0);
    if (n >= 10) return new Response("Please wait a minute", { status: 429 });
    await env.KV.put(lk, String(n + 1), { expirationTtl: 60 });
    const ck = "class:" + classCode + ":" + day;
    const spent = Number((await env.KV.get(ck)) || 0);
    if (spent > DAILY_CLASS_BUDGET) return new Response("Class budget used up", { status: 429 });
    const r = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + env.OPENAI_API_KEY },
      body: JSON.stringify({ model: "gpt-4o-mini", max_tokens: 150, messages: [
        { role: "system", content: "Suggest one way to improve this sentence." }, { role: "user", content: text } ] }),
    });
    const data = await r.json();
    await env.KV.put(ck, String(spent + data.usage.total_tokens));
    return Response.json({ text: data.choices[0].message.content });
  },
};

