const used = new Map<string, number>();
export const DAILY_CLASS_BUDGET = 150;

export async function checkAndCount(classCode: string) {
  const n = used.get(classCode) ?? 0;
  if (n >= DAILY_CLASS_BUDGET) return false;
  used.set(classCode, n + 1);
  return true;
}

export const usage = () => Object.fromEntries(used);

