const DAILY_CLASS_BUDGET = 250000;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const day = new Date().toISOString().slice(0, 10);
    if (url.pathname === "/teacher") {
      return new Response("Tokens used: " + ((await env.KV.get("class:" + url.searchParams.get("code") + ":" + day)) || 0));
    }
    const { learnerId, classCode, question } = await request.json();
    const lk = "l:" + learnerId;
    const n = Number((await env.KV.get(lk)) || 0);
    if (n >= 8) return new Response("Slow down", { status: 429 });
    await env.KV.put(lk, String(n + 1), { expirationTtl: 60 });
    const ck = "class:" + classCode + ":" + day;
    const spent = Number((await env.KV.get(ck)) || 0);
    if (spent > DAILY_CLASS_BUDGET) return new Response("Class budget used up", { status: 429 });
    const r = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "content-type": "application/json", "x-api-key": env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01" },
      body: JSON.stringify({ model: "claude-3-5-haiku-latest", max_tokens: 250,
        system: "Explain science to 11 year olds.", messages: [{ role: "user", content: question }] }),
    });
    const data = await r.json();
    await env.KV.put(ck, String(spent + data.usage.input_tokens + data.usage.output_tokens));
    return Response.json({ reply: data.content[0].text });
  },
};

